package com.finflow.reporting; import org.slf4j.*; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Component; @Component class PaymentEventConsumer{private static final Logger log=LoggerFactory.getLogger(PaymentEventConsumer.class);@KafkaListener(topics="payment.completed.v1")void consume(String payload){log.info("business_event_received type=payment.completed payload={}",payload);}}